#ifndef SYLVARIS_TINYML_GATE_H
#define SYLVARIS_TINYML_GATE_H
/* Auto-generated by tools/v81_benchmark.py from strict 0-50% Sebangau training prefix only.
 * Static RO constants: 12 int8 weights (12 B) + 3 floats (12 B) = 24 B; RAM ring state: ~64 B.
 * Accumulates in float32 using expf() (quantized weights + float execution). Threshold tau=0.60 validated on 50-70% slice. */
#include <stdint.h>
#include <math.h>

static const int8_t SYLVARIS_W_Q8[12] = {-1, 16, -1, -2, -8, 127, 15, -4, 12, 7, -7, -30};
static const float  SYLVARIS_SCALE_Q   = 30.807812f;
static const float  SYLVARIS_BIAS      = -4.745232f;
static const float  SYLVARIS_TAU       = 0.60f;

static inline float sylvaris_tinyml_prob(const float x[12]) {
    float dot = 0.0f;
    for (int i = 0; i < 12; ++i) {
        dot += ((float)SYLVARIS_W_Q8[i]) * x[i];
    }
    float z = (dot / SYLVARIS_SCALE_Q) + SYLVARIS_BIAS;
    if (z > 20.0f) z = 20.0f;
    if (z < -20.0f) z = -20.0f;
    return 1.0f / (1.0f + expf(-z));
}
#endif
